// CBET Fundamentals practice deck (v21). Original exam-style items mapped to the AAMI CBET outline. Data only.
LSA.deck({
  id: "cbet", name: "CBET Fundamentals", icon: "🔌",
  section: 'Engineer Fundamentals', format: 'practice',
  notice: "These are original practice questions written to official public outlines. They are not real past exam items, not an official NCEES or AAMI practice exam, and not a license to practice. Formulas were checked against standard public references. Consult the current FE Reference Handbook and applicable standards for official work.",
  sources: {
    "aami-cbet": ["AAMI: Certified Biomedical Equipment Technician (CBET) exam content outline", "https://aami.org/certifications/cbet/"],
    "openstax-up2": ["OpenStax University Physics Volume 2", "https://openstax.org/details/books/university-physics-volume-2"],
    "hhs-hipaa": ["HHS: HIPAA for Professionals", "https://www.hhs.gov/hipaa/for-professionals/index.html"],
    "nist-csf": ["NIST Cybersecurity Framework", "https://www.nist.gov/cyberframework"],
    "osha-elec": ["OSHA Electrical Safety", "https://www.osha.gov/electrical"],
    "cdc-precautions": ["CDC: Standard Precautions for All Patient Care", "https://www.cdc.gov/infection-control/hcp/standard-precautions/index.html"],
    "cms": ["Centers for Medicare and Medicaid Services", "https://www.cms.gov/"],
  },
  cards: [
    { id: "cb001", ages: 'both', topic: "anatomy", s: "The primary job of the heart is to:", c: ["Filter waste as a kidney would", "Pump blood through the circulatory system", "Exchange gases as an alveolus would", "Store bile"], f: "The heart is a muscular pump that moves blood through the pulmonary and systemic circulations. Gas exchange occurs in the lungs, and the kidneys filter blood.", src: "aami-cbet" },
    { id: "cb002", ages: 'both', topic: "anatomy", s: "Gas exchange between air and blood occurs mainly in the:", c: ["Left ventricle only", "Alveoli of the lungs", "Stomach lining only", "Skin surface only"], f: "Oxygen and carbon dioxide are exchanged across the alveolar-capillary membrane in the lungs. The left ventricle pumps oxygenated blood but does not perform that gas exchange.", src: "aami-cbet" },
    { id: "cb003", ages: 'both', topic: "anatomy", s: "The brain is part of which system?", c: ["The digestive system only", "The nervous system", "The urinary system only", "The integumentary system only"], f: "The brain, spinal cord, and nerves make up the nervous system, which coordinates sensation, control, and many automatic functions.", src: "aami-cbet" },
    { id: "cb004", ages: 'both', topic: "anatomy", s: "Skin is the major organ of which system?", c: ["The respiratory tree only", "The integumentary system", "The skeletal system only", "The endocrine glands only"], f: "Skin, hair, and associated glands form the integumentary system, a barrier that also helps with sensation and temperature control.", src: "aami-cbet" },
    { id: "cb005", ages: 'both', topic: "anatomy", s: "In medical terms, 'hypo-' as a prefix usually means:", c: ["Above or higher than normal", "Below or lower than normal", "Around or surrounding", "Against or opposed to"], f: "Hypo- means under or below (as in hypotension, hypoglycemia). Hyper- means above or excessive. Peri- means around.", src: "aami-cbet" },
    { id: "cb006", ages: 'both', topic: "anatomy", s: "Blood returns to the right atrium of the heart mainly through the:", c: ["Aorta", "Vena cava", "Pulmonary veins only", "Bile duct"], f: "Systemic venous blood enters the right atrium by the venae cavae. The aorta carries blood out of the left ventricle. Pulmonary veins return blood from the lungs to the left atrium.", src: "aami-cbet" },
    { id: "cb007", ages: 'both', topic: "anatomy", s: "The musculoskeletal system includes:", c: ["Only the lungs and airways", "Bones, joints, and muscles that support and move the body", "Only the liver and pancreas as the complete usual rule in ordinary practice", "Only the eyes and ears"], f: "Bones, joints, cartilage, and muscles work together for support, protection, and movement. Lungs belong to the respiratory system.", src: "aami-cbet" },
    { id: "cb008", ages: 'both', topic: "electricity", s: "A 12 V source drives 0.010 A through a resistor. What is the resistance? Use Ohm's law V=IR.", c: ["0.12 ohm", "1,200 ohm", "12 ohm", "120 ohm"], f: "Ohm's law rearranged is $R=V/I=12/0.010=1,200\\,\\Omega$. Using $V I$ or forgetting the decimal in the current are common mistakes.", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A simple series circuit with a voltage source and resistors." },
    { id: "cb009", ages: 'both', topic: "electricity", s: "Two resistors, 2.0 k ohm and 2.0 k ohm, are in series with a 10 V source. What is the current?", c: ["5.0 mA", "2.5 mA", "10 mA", "2.5 A"], f: "Series resistance is $2.0+2.0=4.0$ k$\\Omega$. Current is $I=V/R=10/4000=0.0025$ A $=2.5$ mA.", src: "openstax-up2", img: "img/cbet-series.svg", imgAlt: "A series circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb010", ages: 'both', topic: "electricity", s: "Two 100 ohm resistors are in parallel on a 10 V source. What is the total current from the source?", c: ["0.10 A", "0.20 A", "0.05 A", "20 A"], f: "Each branch draws $10/100=0.10$ A, so the source current is 0.20 A. Equivalently $R_{eq}=50\\,\\Omega$ and $I=10/50=0.20$ A.", src: "openstax-up2", img: "img/cbet-parallel.svg", imgAlt: "A parallel circuit with source V and resistors R1 and R2.", imgAsk: true },
    { id: "cb011", ages: 'both', topic: "electricity", s: "A device draws 2.0 A from a 24 V DC supply. What is the power?", c: ["12 W", "48 W", "26 W", "0.083 W"], f: "Electrical power is $P=VI=24(2.0)=48$ W. Also $P=I^{2}R$ or $V^{2}/R$ once resistance is known.", src: "openstax-up2" },
    { id: "cb012", ages: 'both', topic: "electricity", s: "A line isolation monitor (LIM) in a healthcare isolated power system is used to:", c: ["Replace the need for any equipment grounding in every building", "Warn of leakage or a first fault to ground on an isolated system", "Measure blood pressure", "Generate the ECG waveform"], f: "In isolated power systems used in some critical care areas, a LIM watches for a first ground fault or excessive leakage and alarms so the fault can be found before a second fault occurs.", src: "aami-cbet" },
    { id: "cb013", ages: 'both', topic: "electricity", s: "An uninterruptible power supply (UPS) is used mainly to:", c: ["Increase the wall-outlet voltage to 480 V in every clinic as the complete usual rule in ordinary practice", "Keep critical equipment running during a short utility outage or switchover", "Sterilize instruments", "Replace batteries in implantable devices at the bedside"], f: "A UPS provides short-term power (and often clean power) during a utility interruption until a generator starts or the load can be shut down safely. It is not a sterilizer.", src: "aami-cbet" },
    { id: "cb014", ages: 'both', topic: "healthit", s: "HIPAA rules for protected health information require that workforce members:", c: ["Post patient records on a public website to aid research, without a basis as the complete usual rule in ordinary practice", "Use or share PHI only as needed for treatment, payment, operations, or another permitted purpose", "Share passwords so coworkers can finish charts faster", "Ignore all access policies after hours"], f: "The HIPAA Privacy Rule limits uses and disclosures of PHI and includes a minimum-necessary standard for many uses. Passwords must not be shared. Public posting of records is not permitted just for convenience.", src: "hhs-hipaa" },
    { id: "cb015", ages: 'both', topic: "healthit", s: "A unique hardware address burned into a network interface is called a:", c: ["Subnet mask only", "MAC address", "Default gateway only", "SSID only"], f: "A MAC address identifies a network interface at the link layer. An IP address is a logical network-layer identifier and can change. A gateway is a router address; an SSID names a wireless network.", src: "nist-csf" },
    { id: "cb016", ages: 'both', topic: "healthit", s: "IPv4 address 192.168.1.20 is commonly used as:", c: ["A public address that must be unique worldwide", "A private (non-routable on the public Internet) address", "A MAC address", "A HIPAA form number"], f: "Addresses in 192.168.0.0/16 (and other RFC 1918 ranges) are private. They are not unique on the public Internet and are typically translated at a firewall.", src: "nist-csf" },
    { id: "cb017", ages: 'both', topic: "healthit", s: "The PING utility is used mainly to:", c: ["Format a hard drive", "Test whether a host is reachable and measure round-trip time", "Calibrate a defibrillator as the complete usual rule in ordinary practice", "Patch an operating system"], f: "PING sends ICMP echo requests and reports whether replies return. It is a basic network diagnostic, not a clinical calibration or OS-update tool.", src: "nist-csf" },
    { id: "cb018", ages: 'both', topic: "healthit", s: "A medical device that cannot talk to the electronic medical record, even though the network is up, may have a problem with:", c: ["The color of the nurse-call light only as the complete usual rule in ordinary practice", "The interface or middleware that maps device data to the EMR", "The building water pressure only", "The cafeteria menu"], f: "Device-to-EMR integration often uses a gateway or middleware and a standard such as HL7. A mapping, license, or interface engine fault can block data even when the LAN is healthy.", src: "aami-cbet" },
    { id: "cb019", ages: 'both', topic: "healthit", s: "NIST cybersecurity guidance for systems that handle sensitive data emphasizes:", c: ["Sharing one password for the whole clinic as the complete usual rule in ordinary practice", "Identify, protect, detect, respond, and recover functions", "Never applying security patches", "Posting PHI to a public forum for backup"], f: "The NIST Cybersecurity Framework organizes work into functions such as identify, protect, detect, respond, and recover. Patching, access control, and monitoring support those functions.", src: "nist-csf" },
    { id: "cb020", ages: 'both', topic: "healthit", s: "A workstation will not boot and the display stays dark, even on a known-good monitor. A useful early hardware check is:", c: ["Reimaging the EMR server first, before any local check", "Power supply rails, connections, and whether the board posts", "Replacing the hospital generator first", "Changing the patient's diet order"], f: "A dead workstation is often a local power, cable, memory, or motherboard problem. Confirm power and basic POST before blaming enterprise servers.", src: "nist-csf" },
    { id: "cb021", ages: 'both', topic: "healthit", s: "Applying OS and application patches on networked medical systems is important because:", c: ["Patches always increase leakage current", "Unpatched systems are a common path for malware and data breaches", "Patches replace electrical safety testing as the complete usual rule in ordinary practice", "Vendors never require them"], f: "Timely, tested patching reduces known vulnerabilities. Clinical systems still need a change process so a patch does not break a device or workflow.", src: "nist-csf" },
    { id: "cb022", ages: 'both', topic: "healthit", s: "A wireless access point is used to:", c: ["Measure ECG amplitude", "Connect Wi-Fi clients to the wired network", "Step 120 V down to 5 V for logic boards", "Sterilize probes"], f: "An access point bridges wireless clients (and sometimes other APs) to the LAN. It is not a clinical instrument or a power transformer.", src: "nist-csf" },
    { id: "cb023", ages: 'both', topic: "healthit", s: "A switch, as opposed to a simple hub, typically:", c: ["Always broadcasts every frame to every port, by design of a modern switch", "Forwards frames toward the correct port based on MAC addresses", "Assigns HIPAA ID numbers", "Provides isolated power to an OR"], f: "A switch learns MAC addresses and forwards unicast frames out the needed port. A hub repeats to all ports. This reduces collisions and improves performance.", src: "nist-csf" },
    { id: "cb024", ages: 'both', topic: "healthit", s: "A default gateway is:", c: ["The MAC address of a printer only as the complete usual rule in ordinary practice", "The router address a host uses to reach other networks", "A second display name", "The hospital's street address"], f: "If a destination is not on the local subnet, the host sends packets to its default gateway, which then routes them onward.", src: "nist-csf" },
    { id: "cb025", ages: 'both', topic: "healthit", s: "Hardening a Windows PC used near a medical device should include:", c: ["A shared 'user' login posted on the monitor", "Unique accounts, a password or other authentication, and timely updates", "Disabling the screen lock for convenience, always as the complete usual rule in ordinary practice", "Turning off all logging for speed"], f: "Unique credentials, authentication, auto-lock, patching, and least privilege reduce the chance that one compromised session exposes PHI or device control. Shared posted passwords are a common audit finding.", src: "hhs-hipaa" },
    { id: "cb026", ages: 'both', topic: "healthit", s: "A virtual server is:", c: ["A type of infusion pump motor as the complete usual rule in ordinary practice", "A guest operating system running on a hypervisor, sharing physical hardware", "A grounding electrode", "A paper chart rack"], f: "Virtualization lets multiple servers share one host. Medical device vendors may or may not support a virtualized server, so the support statement matters.", src: "nist-csf" },
    { id: "cb027", ages: 'both', topic: "healthit", s: "Cloud computing for a clinic means, at a basic level:", c: ["Moving the MRI magnet to the roof as the complete usual rule in ordinary practice", "Using computing resources delivered over a network, often off site, under a service model", "A new name for a 9 V battery", "Printing more paper labels"], f: "Cloud services provide on-demand computing or applications over a network. HIPAA still applies: a business associate agreement and security controls are needed when PHI is involved.", src: "hhs-hipaa" },
    { id: "cb028", ages: 'both', topic: "healthit", s: "A cable tester or toner is most useful when you need to:", c: ["Calibrate a scale", "Identify or verify a copper network run and its pairs", "Measure blood oxygen", "Program an infusion dose as the complete usual rule in ordinary practice"], f: "Testers and toners help prove a cable's identity, continuity, and sometimes pair mapping or length. They do not replace clinical calibration tools.", src: "nist-csf" },
    { id: "cb029", ages: 'both', topic: "healthit", s: "HHS has published cybersecurity performance goals for healthcare because:", c: ["They replace all electrical safety standards as the complete usual rule in ordinary practice", "Attacks on hospitals and clinics can disrupt care and expose PHI", "They ban the use of any network in a clinic", "They set the price of a CT tube"], f: "Healthcare is a frequent ransomware and breach target. Federal performance goals and HIPAA security requirements aim to keep systems and PHI safer so care can continue.", src: "hhs-hipaa" },
    { id: "cb030", ages: 'both', topic: "healthit", s: "A KVM switch is used to:", c: ["Measure potassium, volume, and magnesium in blood as the complete usual rule in ordinary practice", "Share a keyboard, video display, and mouse among more than one computer", "Isolate a power system in an OR", "Patch a Linux kernel"], f: "KVM hardware (or software) lets one set of human-interface devices control multiple computers. It is not a lab analyzer or an isolated-power device.", src: "nist-csf" },
    { id: "cb031", ages: 'both', topic: "function", s: "Korotkoff sounds are used when measuring:", c: ["Body temperature in the ear only as the complete usual rule in ordinary practice", "Blood pressure with a cuff and stethoscope (or a simulator of that method)", "Expired oxygen only", "Skin color only"], f: "Korotkoff sounds are the noises heard over an artery as a cuff deflates, used in auscultatory blood-pressure measurement. Automatic NIBP devices often use oscillometry instead, but the underlying clinical quantity is still blood pressure.", src: "aami-cbet" },
    { id: "cb032", ages: 'both', topic: "function", s: "Einthoven's triangle refers to:", c: ["A method for leveling a surgical table", "The three standard limb leads of the ECG", "A radiation warning sign", "A battery chemistry"], f: "Einthoven's triangle is formed by leads I, II, and III on the right arm, left arm, and left leg. It is a basic ECG lead model, not a table or safety-sign topic.", src: "aami-cbet", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform showing P, QRS, and T waves." },
    { id: "cb033", ages: 'both', topic: "function", s: "On a normal ECG, the QRS complex mainly represents:", c: ["Atrial depolarization only (the P wave)", "Ventricular depolarization", "Ventricular repolarization only (the T wave)", "A blood-pressure Korotkoff sound"], f: "The P wave is atrial depolarization, the QRS is ventricular depolarization, and the T wave is ventricular repolarization. Technicians should recognize a normal pattern without diagnosing a patient.", src: "aami-cbet", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG waveform with the P wave, QRS complex, and T wave labeled.", imgAsk: true },
    { id: "cb034", ages: 'both', topic: "function", s: "A defibrillator analyzer is used to:", c: ["Deliver a shock to a patient as a therapy device as the complete usual rule in ordinary practice", "Measure output energy and related functions of a defibrillator in a test setting", "Replace the hospital's utility transformer", "Sterilize paddles with steam"], f: "A defibrillator analyzer is test equipment. It lets a technician verify delivered energy and other functions on a schedule, not treat a patient.", src: "aami-cbet" },
    { id: "cb035", ages: 'both', topic: "function", s: "An electrical safety analyzer is used to:", c: ["Display a live 12-lead ECG for diagnosis as the complete usual rule in ordinary practice", "Measure leakage current, ground resistance, and similar safety points on a medical device", "Measure a patient's blood pressure", "Program an infusion pump drug library"], f: "Safety analyzers check protective earth, insulation, and leakage against the limits in the applicable standard (for example IEC 60601 or a facility policy based on NFPA 99). They are not clinical monitors.", src: "aami-cbet" },
    { id: "cb036", ages: 'both', topic: "function", s: "A physiologic simulator is used to:", c: ["Treat a patient in place of a monitor as the complete usual rule in ordinary practice", "Provide known test signals (ECG, pressure, SpO2, and similar) to a monitor", "Generate isolated power for an OR", "Replace a UPS battery pack"], f: "Simulators let you test a monitor or module with a known waveform or value so you can tell a device fault from a cable or electrode problem.", src: "aami-cbet" },
    { id: "cb037", ages: 'both', topic: "function", s: "Blood pressure in the clinic is commonly reported in:", c: ["Lumens", "Millimeters of mercury (mmHg)", "Becquerel as the complete usual rule in ordinary practice", "Siemens"], f: "Arterial blood pressure is measured in mmHg. Lumens measure light, becquerel is activity, and siemens is conductance.", src: "aami-cbet" },
    { id: "cb038", ages: 'both', topic: "function", s: "A pulse oximeter estimates:", c: ["Core liver enzyme levels", "Arterial oxygen saturation from light absorbed by a pulsatile vascular bed", "End-tidal carbon dioxide directly, in every device as the complete usual rule in ordinary practice", "Intracranial pressure"], f: "Pulse oximetry uses at least two light wavelengths and a pulsatile signal to estimate SpO2. EtCO2 is a capnography measurement, not the same sensor.", src: "aami-cbet" },
    { id: "cb039", ages: 'both', topic: "function", s: "End-tidal CO2 (EtCO2) monitoring is used mainly to:", c: ["Measure only room-air oxygen fraction", "Follow carbon dioxide in exhaled gas, often during sedation or ventilation", "Replace a pulse oximeter in every case as the complete usual rule in ordinary practice", "Set the hospital's fire-alarm zone"], f: "Capnography reports CO2 in exhaled gas and is a key check of ventilation and airway integrity. It complements, rather than always replaces, oximetry.", src: "aami-cbet" },
    { id: "cb040", ages: 'both', topic: "function", s: "A telemetry system in a hospital is used to:", c: ["Sterilize endoscopes", "Send physiologic waveforms from a mobile patient to a central station", "Generate 480 V for imaging rooms as the complete usual rule in ordinary practice", "Mix IV medications"], f: "Telemetry uses radios or a network to carry ECG and related signals so a patient can move while being watched at a central station.", src: "aami-cbet" },
    { id: "cb041", ages: 'both', topic: "function", s: "An infusion pump (LVP or syringe) is designed to:", c: ["Shock a fibrillating heart", "Deliver fluids or medications at a controlled rate", "Measure only body temperature", "Provide mechanical ventilation of the lungs"], f: "Infusion devices control rate and volume. Different types (large-volume, syringe, PCA, and injectors) fit different therapies, but the core function is controlled delivery.", src: "aami-cbet" },
    { id: "cb042", ages: 'both', topic: "function", s: "A PCA pump is intended to:", c: ["Ventilate a patient who cannot breathe as the complete usual rule in ordinary practice", "Let a patient request extra doses of pain medicine within programmed limits", "Record a 12-lead ECG", "Warm a whole operating table"], f: "Patient-controlled analgesia pumps give a programmed basal and/or demand dose with lockout limits. They are not ventilators or ECG machines.", src: "aami-cbet" },
    { id: "cb043", ages: 'both', topic: "function", s: "A ventilator is life-support equipment whose basic job is to:", c: ["Only measure blood pressure as the complete usual rule in ordinary practice", "Support or replace a patient's breathing", "Only record an ECG", "Only warm blankets"], f: "Ventilators deliver a controlled gas pattern to support ventilation. They require trained use, alarms, and backup power. They are not simple monitors.", src: "aami-cbet" },
    { id: "cb044", ages: 'both', topic: "function", s: "An external defibrillator is used to:", c: ["Pace only a chronic low heart rate as a permanent implant as the complete usual rule in ordinary practice", "Deliver a controlled electrical shock to treat certain dangerous heart rhythms, in a clinical protocol", "Measure only oxygen saturation", "Replace a wall suction regulator"], f: "Defibrillators treat shockable arrhythmias under clinical protocols. An implanted pacemaker is a different device. External transcutaneous pacing is a related but separate function on some units.", src: "aami-cbet" },
    { id: "cb045", ages: 'both', topic: "function", s: "An electrosurgical unit (ESU) is used in the operating room to:", c: ["Ventilate the patient", "Cut or coagulate tissue with a high-frequency current", "Record fetal heart rate as its only function", "Sterilize the whole room by filling it with steam"], f: "ESUs deliver RF current through an active electrode, with a return path (monopolar) or between the tips (bipolar). Safe use depends on return-electrode integrity, accessories, and smoke control.", src: "aami-cbet" },
    { id: "cb046", ages: 'both', topic: "function", s: "A surgical table and surgical lights are perioperative equipment used to:", c: ["Deliver a defibrillation shock as the complete usual rule in ordinary practice", "Position the patient and illuminate the field", "Measure only laboratory pH", "Generate the EMR backup"], f: "Tables position and support the patient; lights provide a bright, often adjustable, field. Neither device is a defibrillator or a lab analyzer.", src: "aami-cbet" },
    { id: "cb047", ages: 'both', topic: "function", s: "A steam sterilizer (autoclave) uses which combination as its basic killing method?", c: ["Only dry room air at 20 C", "Saturated steam under pressure for a defined time and temperature", "Only a UV night-light", "Only a paper wrap with no heat as the complete usual rule in ordinary practice"], f: "Steam sterilizers use moist heat at a controlled temperature and time (and often a documented load process). Dry, cool air or a night-light is not a sterilization cycle.", src: "aami-cbet" },
    { id: "cb048", ages: 'both', topic: "function", s: "A laboratory centrifuge is used to:", c: ["Ventilate a patient", "Separate components of a sample by spinning it", "Deliver an IV bolus", "Image a joint with X-rays as the complete usual rule in ordinary practice"], f: "Centrifuges spin samples so denser components move outward. Imbalance, lid interlocks, and speed verification are typical safety and performance points.", src: "aami-cbet" },
    { id: "cb049", ages: 'both', topic: "function", s: "A laboratory refrigerator or freezer is important because:", c: ["It is a substitute for a defibrillator", "Many reagents and samples must stay in a controlled temperature range", "It sterilizes steel tools by freezing them as the complete usual rule in ordinary practice", "It provides isolated power to an OR"], f: "Lab cold storage must hold a set range, often with alarms and monitoring. Freezing is not a sterilizer for surgical tools, and it is not a power system.", src: "aami-cbet" },
    { id: "cb050", ages: 'both', topic: "function", s: "An ultrasound imager forms pictures mainly by:", c: ["Using a strong static magnetic field as in MRI", "Sending high-frequency sound and receiving echoes", "Using ionizing gamma cameras only", "Using a thermal camera only"], f: "Diagnostic ultrasound transmits pulses and listens for reflections. MRI uses magnetic fields and radiofrequency; nuclear medicine uses radioactive tracers.", src: "aami-cbet" },
    { id: "cb051", ages: 'both', topic: "function", s: "A digital multimeter (DVM) in a shop is used to:", c: ["Measure only a patient's core temperature as the complete usual rule in ordinary practice", "Measure voltage, current, or resistance in a circuit under test", "Deliver pacing pulses to a heart", "Print wristbands"], f: "A DVM is general test equipment. Use it on de-energized circuits where required, with the right function and range, and never as a substitute for a medical-grade safety analyzer when that test is needed.", src: "openstax-up2" },
    { id: "cb052", ages: 'both', topic: "function", s: "An SCD (sequential compression device) is used to:", c: ["Defibrillate the heart", "Inflate garments on a limb in a cycle to help reduce stasis", "Provide mechanical ventilation as the complete usual rule in ordinary practice", "Measure end-tidal CO2"], f: "SCDs apply intermittent pneumatic compression, often to the legs, as a preventive therapy. They are not life-support ventilators or defibrillators.", src: "aami-cbet" },
    { id: "cb053", ages: 'both', topic: "function", s: "A patient warmer or thermal blanket system is used to:", c: ["Record an ECG as its only function", "Help manage a patient's body temperature", "Measure only urine volume", "Provide suction"], f: "Temperature-management devices heat or, in some systems, also cool a patient under a protocol. Over- or under-heating is a risk, so probes, alarms, and accessories matter.", src: "aami-cbet" },
    { id: "cb054", ages: 'both', topic: "function", s: "A wall suction regulator is used to:", c: ["Raise oxygen concentration in a blender", "Control vacuum applied to a suction circuit", "Pace the heart", "Measure NIBP"], f: "Suction regulators set and limit vacuum from a wall or portable source. They are not oxygen blenders or pacing devices.", src: "aami-cbet" },
    { id: "cb055", ages: 'both', topic: "function", s: "A fetal monitor typically tracks:", c: ["Only adult 12-lead ECG as its designed purpose as the complete usual rule in ordinary practice", "Fetal heart rate and uterine activity (for example TOCO or IUP)", "Only laboratory centrifuge speed", "Only steam-sterilizer pressure"], f: "Fetal monitors record FHR and contractions (TOCO on the abdomen, or intrauterine pressure when indicated) so clinicians can assess well-being in labor or testing.", src: "aami-cbet" },
    { id: "cb056", ages: 'both', topic: "function", s: "An anesthesia machine, at a basic level, is used to:", c: ["Only wash and sterilize instruments as the complete usual rule in ordinary practice as the complete usual rule in ordinary practice", "Deliver a controlled mixture of gases and anesthetic agent and support ventilation during anesthesia", "Only store medical records", "Only measure a newborn's weight"], f: "Anesthesia workstations blend gases, vaporize agent, and ventilate, with many safety interlocks and scavengers. They are life-support systems and are not sterilizers.", src: "aami-cbet" },
    { id: "cb057", ages: 'both', topic: "function", s: "An external pacemaker (for example a transcutaneous or temporary external unit) is used to:", c: ["Measure only SpO2", "Deliver pacing pulses when a temporary external strategy is indicated", "Warm IV fluids as its only function as the complete usual rule in ordinary practice", "Replace a steam sterilizer"], f: "External or temporary pacemakers provide pacing pulses under a clinical protocol. They are not oximeters or sterilizers. Implantable pacemakers are a different class of device.", src: "aami-cbet" },
    { id: "cb058", ages: 'both', topic: "function", s: "A fluid warmer is used in perioperative or emergency care to:", c: ["Defibrillate a patient as the complete usual rule in ordinary practice", "Warm fluids or blood products before they are infused, within its labeled use", "Record EEG only", "Replace a UPS"], f: "Fluid warmers reduce the chance of hypothermia from cold infusions. They must be used with the right disposables and temperature limits. They are not defibrillators.", src: "aami-cbet" },
    { id: "cb059", ages: 'both', topic: "function", s: "A spirometer is a diagnostic device used to:", c: ["Shock the heart", "Measure how much and how fast a person can move air in a breathing test", "Dialyze blood", "Measure only blood glucose as the complete usual rule in ordinary practice"], f: "Spirometry records volumes and flow for pulmonary testing. Calibration with a syringe and infection-control practices are typical technical points.", src: "aami-cbet" },
    { id: "cb060", ages: 'both', topic: "function", s: "An otoscope is used to:", c: ["Look at the retina as its main designed use", "Look into the ear canal", "Measure only blood pressure", "Ventilate the lungs"], f: "An otoscope illuminates and magnifies the ear canal and eardrum. An ophthalmoscope is the related tool for the eye.", src: "aami-cbet" },
    { id: "cb061", ages: 'both', topic: "troubleshooting", s: "A monitor is completely dark, and no power light is on. The wall outlet is live. A sound first check is:", c: ["Replacing the patient's heart first", "The power cord, switch, inlet fuse or breaker, and then the supply", "Recalibrating a steam sterilizer first as the complete usual rule in ordinary practice", "Changing the EMR vendor first"], f: "No lights often means no power reaching the device. Check the obvious path (cord, switch, fuse or breaker, then the supply) before swapping major boards or blaming the network.", src: "aami-cbet" },
    { id: "cb062", ages: 'both', topic: "troubleshooting", s: "A physiologic monitor shows a flat ECG and a 'leads off' message, but a simulator on the same cable is normal. The more likely problem is:", c: ["A failed display backlight only, because the trace would still be stored", "The electrodes, skin prep, or lead wires on the patient", "The hospital generator", "The steam supply"], f: "If a known-good simulator works, the input and cable path are probably fine. The next place to look is the connection to the patient: electrodes, prep, and lead wires.", src: "aami-cbet", img: "img/cbet-ecg.svg", imgAlt: "A simple ECG-style waveform used as a known test pattern." },
    { id: "cb063", ages: 'both', topic: "troubleshooting", s: "Two work orders arrive: a ventilator in use on a patient has a critical alarm, and a scale in a clinic is slightly out of date for its check. Which should you handle first?", c: ["The scale, because it is easier", "The in-use ventilator, because of risk and urgency", "Neither, until the next business day as the complete usual rule in ordinary practice", "The scale, because it is older"], f: "Prioritize by risk, urgency, and effect on care. Life-support equipment in use comes before a noncritical clinic scale.", src: "aami-cbet" },
    { id: "cb064", ages: 'both', topic: "troubleshooting", s: "A nurse reports 'the infusion pump is broken' after a dose was entered incorrectly and the pump alarmed as designed. This is best classified as:", c: ["A complete device failure in every case as the complete usual rule in ordinary practice", "A use error (or use-related issue), after you confirm the pump works", "A steam-sterilizer fault", "A utility power outage"], f: "If the device alarms and behaves as designed when a wrong entry is made, the event may be a use error. Still verify the pump, then help with training or a workflow change. Do not skip the technical check.", src: "aami-cbet" },
    { id: "cb065", ages: 'both', topic: "troubleshooting", s: "One telemetry transmitter on a hall drops out, but the whole unit's other transmitters are fine. You should first suspect:", c: ["A campus-wide network collapse only", "That transmitter, its battery, its antenna, or a local dead zone", "A failure of every central station in the hospital", "The cafeteria steam pot"], f: "A single-device problem is more often local (battery, antenna, that radio, or a dead spot) than a system-wide failure. Compare with nearby working devices.", src: "aami-cbet" },
    { id: "cb066", ages: 'both', topic: "troubleshooting", s: "Every telemetry display on a unit fails at once, while other hospital networks still work. That pattern suggests:", c: ["A single patient's electrode pack only as the complete usual rule in ordinary practice", "A system-level problem (access point, controller, or that unit's network path)", "A single bed scale", "A single cracked otoscope bulb"], f: "When many devices of one system fail together, look at shared infrastructure, not one accessory. Isolate whether the fault is wireless, a switch, a server, or a central station.", src: "aami-cbet" },
    { id: "cb067", ages: 'both', topic: "troubleshooting", s: "A newly installed monitor will not send data to the EMR, but waveforms look correct at the bedside. A useful early step is:", c: ["Replace the patient's IV catheter as a first technical step", "Confirm network settings, device ID, and the interface or middleware status", "Increase the defibrillator energy", "Disable all logging"], f: "Bedside operation can be fine while ADT or results never reach the record because of IP, ports, time, a certificate, or a mapping in middleware. Check those before swapping a working display.", src: "aami-cbet" },
    { id: "cb068", ages: 'both', topic: "troubleshooting", s: "A staff member needs a short in-service on a new vital-signs monitor. Your communication should be:", c: ["A guess about off-label workarounds you have not checked", "Clear, in plain language, and limited to safe, approved use", "A joke that patients' names can be posted publicly", "A request that they ignore all alarms"], f: "Technicians often train clinicians on proper use. Stay inside approved functions, be clear, and do not invent workarounds that bypass safety.", src: "aami-cbet" },
    { id: "cb069", ages: 'both', topic: "troubleshooting", s: "A defibrillator fails an energy-output test on a defibrillator analyzer, but the device powers on. The right next path is:", c: ["Return it to the crash cart and hope the next shock is accurate", "Remove it from service, investigate, and repair or escalate per policy", "Ignore the test because the display lights work", "Use it as a toy for practice shocks on staff"], f: "A failed energy test means the device must not stay in clinical service. Tag it, document, and follow the service procedure. Do not use people as test loads.", src: "aami-cbet" },
    { id: "cb070", ages: 'both', topic: "troubleshooting", s: "An ESU repeatedly faults with a return-electrode alarm. A practical first check is:", c: ["The cafeteria menu", "The return pad, its cable, and how it is applied, then the generator's return circuit", "The MRI quench line", "The patient-entertainment TV guide as the complete usual rule in ordinary practice"], f: "Return-electrode (REM or CQM) alarms are often an accessory or application issue. Confirm the pad and cable before condemning the generator, then test the unit if the accessories are good.", src: "aami-cbet" },
    { id: "cb071", ages: 'both', topic: "troubleshooting", s: "A syringe pump stops and reports occlusion. A sound first set of checks is:", c: ["The roof chiller only", "The tubing, clamps, position, and whether the alarm is real, then the pump", "The fire-alarm panel only as the complete usual rule in ordinary practice", "The parking-gate arm"], f: "Occlusion alarms are often clamps, kinks, a closed stopcock, or a high back-pressure site. Rule those out, then test the pump's pressure sensing if the fluid path is clear.", src: "aami-cbet" },
    { id: "cb072", ages: 'both', topic: "troubleshooting", s: "A PCA pump can be started, but the lockout interval does not match the order. After confirming the order, you should:", c: ["Tell the patient to ignore the lockout", "Treat it as a programming or device-configuration problem and keep the pump out of use until it is right", "Raise the limit yourself without authority", "Leave it in service because the motor still runs as the complete usual rule in ordinary practice"], f: "A lockout that does not match the prescribed program is a safety issue. Do not leave it in service or change therapy limits without the proper clinical and technical process.", src: "aami-cbet" },
    { id: "cb073", ages: 'both', topic: "troubleshooting", s: "A feeding pump free-flows when the door is open and no set is loaded correctly. That is:", c: ["Normal for every pump, so leave it in use", "A serious safety fault; take the pump out of service", "A cosmetics issue only", "A reason to add more free-flow in testing"], f: "Free-flow of enteral or IV fluid when the set is not properly engaged is a serious hazard. The device should be removed from service and repaired or replaced.", src: "aami-cbet" },
    { id: "cb074", ages: 'both', topic: "troubleshooting", s: "A laboratory centrifuge will not start, and the lid interlock light stays open even when the lid is closed. A likely cause is:", c: ["A wrong ECG lead placement", "A lid switch, latch, or interlock fault", "A failed steam jacket on a sterilizer in another room", "A wireless SSID typo only"], f: "Centrifuges should not run with the lid open. If the interlock never sees 'closed,' look at the switch, latch, and wiring before replacing a motor.", src: "aami-cbet" },
    { id: "cb075", ages: 'both', topic: "troubleshooting", s: "A lab refrigerator used for reagents is at 12 C, above its set range, and the alarm did not call. You should:", c: ["Leave the reagents in place until next month", "Protect the contents, take the box out of service as needed, and find why cooling and the alarm both failed", "Use the box as a room heater", "Disable the remaining alarms so it looks fine as the complete usual rule in ordinary practice"], f: "Out-of-range storage can ruin reagents or samples. Safeguard the contents, then repair the refrigeration and the alarm path. Do not silence alarms to hide the problem.", src: "aami-cbet" },
    { id: "cb076", ages: 'both', topic: "troubleshooting", s: "An otoscope light is dim. The handle has fresh batteries. A simple next check is:", c: ["The hospital's MRI zonings", "The lamp, contacts, and the head connection", "The steam generator pressure as the complete usual rule in ordinary practice", "The EMR database index"], f: "A dim otoscope is often a lamp, dirty contacts, or a poor connection in the head or handle. Power is already plausible if the batteries are good.", src: "aami-cbet" },
    { id: "cb077", ages: 'both', topic: "troubleshooting", s: "A scale used for medication dosing reads 0.4 kg high on a known test weight. You should:", c: ["Leave it in service and tell staff to subtract 0.4 kg in their heads", "Remove it from clinical dosing use until it is calibrated or replaced", "Ignore the error because it is 'only' 0.4 kg", "Use it to weigh gas cylinders only, with the same error, for drugs"], f: "A scale used for dosing must be accurate. Take it out of that use, calibrate or repair it, and document. Mental corrections are not a safe standing practice.", src: "aami-cbet" },
    { id: "cb078", ages: 'both', topic: "troubleshooting", s: "A stress-test ECG is noisy only when the treadmill is running. A useful direction is:", c: ["Replace the hospital boiler first", "Look for motion, cable routing, grounding, or interference from the treadmill drive", "Assume the patient simulator in the shop is the only cause as the complete usual rule in ordinary practice", "Increase the defibrillator default energy"], f: "Noise that appears only when a treadmill runs often points to motion artifact, cable placement, or electrical interference from the drive. Compare with a standing ECG.", src: "aami-cbet" },
    { id: "cb079", ages: 'both', topic: "troubleshooting", s: "An ultrasound unit powers on but shows no image, and a known-good probe on that connector is also dark. The fault is more likely:", c: ["Always the last probe you used, even if a known-good probe also fails", "In the system (connector, board, or software), not only one probe", "The room light switch only", "The paper in a nearby printer only"], f: "If a known-good probe also fails on that port, look at the system side. If only one probe fails on a known-good port, look at that probe.", src: "aami-cbet" },
    { id: "cb080", ages: 'both', topic: "troubleshooting", s: "A pulse-oximeter reading is blank on a patient with cold fingers, but a simulator at the same cable reads 98%. This suggests:", c: ["A failed simulator, because it showed 98%", "A poor peripheral signal, not a proved monitor failure", "A need to ignore all oximetry alarms in the unit", "A steam leak"], f: "A simulator isolates the device and cable. A good simulator result with a poor patient signal points to perfusion, placement, or ambient light, which clinicians may address. Still treat alarms seriously.", src: "aami-cbet" },
    { id: "cb081", ages: 'both', topic: "troubleshooting", s: "A ventilator in the shop fails a volume check on a test lung, outside its allowed error. You should:", c: ["Send it to a patient room because the display is pretty", "Keep it out of service and repair or escalate it", "Raise the allowed error yourself on the sticker", "Disable the test-lung alarms and pass it"], f: "Life-support equipment that fails a performance test stays out of service until it is corrected and verified. Do not 'pass' it by changing limits without authority.", src: "aami-cbet" },
    { id: "cb082", ages: 'both', topic: "troubleshooting", s: "A balloon pump (IABP) in use has a gas-loss alarm. Your first priority is:", c: ["Walk away to finish a scale check first", "Support the clinical team and the patient, then follow the emergency procedure for that device", "Open the helium circuit as a casual demo as the complete usual rule in ordinary practice", "Reset billing codes"], f: "An IABP is life-support. A leak or gas-loss alarm is urgent. Help the clinical team with the approved emergency steps and a backup plan; do not treat it as a routine shop call while it is on a patient.", src: "aami-cbet" },
    { id: "cb083", ages: 'both', topic: "troubleshooting", s: "An anesthesia machine fails a pre-use leak test. The correct action is:", c: ["Start the case and hope the leak is small", "Do not use it for a case until the leak is found and the check passes", "Bypass the check because the last case was fine", "Cover the leak with tape and proceed without a test as the complete usual rule in ordinary practice"], f: "Pre-use checks exist to catch leaks and other faults before a patient is anesthetized. A failed leak test takes the machine out of use until it is repaired and it passes.", src: "aami-cbet" },
    { id: "cb084", ages: 'both', topic: "troubleshooting", s: "A surgical table will not unlock to reposition, and the patient is on the table. You should:", c: ["Force the frame with a large pry bar as a first step as the complete usual rule in ordinary practice", "Keep the patient safe, follow the emergency-unlock procedure if there is one, and do not force unknown parts", "Cut the main structural weld as a first step", "Leave the room without telling the team"], f: "With a patient on the table, safety and an approved emergency release come first. Do not improvise with force that could injure the patient or wreck the table.", src: "aami-cbet" },
    { id: "cb085", ages: 'both', topic: "troubleshooting", s: "An infant warmer's skin-temperature probe is off the skin, and the unit is in servo mode. The unsafe pattern to watch for is:", c: ["The warmer will always cool the room instead", "The heater may overshoot because it does not see a true skin temperature", "The probe being off has no effect in servo mode", "The unit will automatically switch to a sterilizer cycle"], f: "In servo (skin) mode the heater is driven by the probe. A loose or detached probe can lead to overheating. Check probe placement and mode, and follow the device's alarm behavior.", src: "aami-cbet" },
    { id: "cb086", ages: 'both', topic: "troubleshooting", s: "A therapeutic ultrasound unit in physical therapy has a worn sound head and a failed completeness-of-output check. You should:", c: ["Turn the power up to 'make up' for the worn head as the complete usual rule in ordinary practice", "Take it out of service until the applicator and output are corrected", "Let treatments continue with a note on the door", "Ignore the test because the timer still works"], f: "If the applicator or output is out of specification, treatments should stop until repair and a passing test. Turning power up is not a safe fix.", src: "aami-cbet" },
    { id: "cb087", ages: 'both', topic: "troubleshooting", s: "A video integration system in an OR has no image on the main display, but the endoscope's local screen works. A useful path is:", c: ["Replace the endoscope light source first, even though the local screen is good", "Trace the video route: cables, switcher, input selection, and that display", "Rebuild the steam generator", "Reimage every PC in medical records first"], f: "A good local image means the scope is producing video. The fault is likely in routing, selection, cables, or the destination display.", src: "aami-cbet" },
    { id: "cb088", ages: 'both', topic: "troubleshooting", s: "A circulating nurse says a new device 'does not work like the old one.' The best first technical step is:", c: ["Tell them the new device is always wrong, with no check as the complete usual rule in ordinary practice", "Ask what they expected, confirm settings, and compare to the manual and a known-good unit", "Change clinical set-points without authority", "Walk away without a record"], f: "Many 'it does not work' calls are setup or a difference in workflow. Listen, compare with the manual or a known-good unit, and document. Then repair if there is a real fault.", src: "aami-cbet" },
    { id: "cb089", ages: 'both', topic: "troubleshooting", s: "A module in a physiologic monitor loses only the IBP channel, while ECG and NIBP still work. That pattern suggests:", c: ["A total failure of the whole monitor in every case as the complete usual rule in ordinary practice", "A fault in that pressure channel, its cable, or its transducer interface", "A building-wide power loss", "A failed hospital boiler"], f: "When one parameter fails and others on the same monitor work, start with that channel and its accessories before replacing the entire platform.", src: "aami-cbet" },
    { id: "cb090", ages: 'both', topic: "troubleshooting", s: "You finish a repair on a life-support device. Before it returns to service you should:", c: ["Send it back with no test, to save time", "Test the functions that were affected and complete the required documentation", "Erase the work-order history so no one sees the fault as the complete usual rule in ordinary practice", "Skip electrical safety checks that policy requires"], f: "Return-to-service needs verification of the repair, required safety and performance checks, and a record in the CMMS. Skipping tests or records is not acceptable.", src: "aami-cbet" },
    { id: "cb091", ages: 'both', topic: "safety", s: "A protective earth (ground) conductor on a medical device power cord is there mainly to:", c: ["Carry the normal load current in place of the hot conductor, by design as the complete usual rule in ordinary practice", "Provide a low-impedance fault path so a breaker or protection can operate and touch voltage stays low", "Replace the need for any insulation", "Decorate the plug"], f: "The grounding conductor is a safety path for fault current, not the normal load path. NFPA 99 and IEC 60601 address grounding and leakage in healthcare electrical systems and equipment; consult those standards for limits and methods.", src: "osha-elec", img: "img/cbet-plug.svg", imgAlt: "A three-prong plug with the hot, neutral, and ground pins labeled.", imgAsk: true },
    { id: "cb092", ages: 'both', topic: "safety", s: "Macroshock and microshock are different because:", c: ["Macroshock applies only to toys, never to people", "Microshock concerns small currents that can be dangerous if they reach the heart through a conductive path", "Microshock is only a radio term", "They are two names for the same floor-outlet test as the complete usual rule in ordinary practice"], f: "Macroshock is a shock through the intact body. Microshock refers to much smaller currents that can be hazardous if a conductive path (for example a catheter or lead) reaches the heart. Design and testing of patient connections take that risk into account. See IEC 60601 and NFPA 99 for the official limits and tests.", src: "aami-cbet" },
    { id: "cb093", ages: 'both', topic: "safety", s: "A GFCI device is intended to:", c: ["Increase leakage to the patient on purpose", "Open the circuit when it detects a dangerous imbalance between hot and neutral current", "Replace the equipment grounding conductor in every medical device, always", "Measure ECG amplitude"], f: "A GFCI compares outgoing and returning current and trips when the difference suggests leakage to ground. It is a personnel-protection device. It does not replace all other grounding and leakage requirements in medical equipment standards.", src: "osha-elec" },
    { id: "cb094", ages: 'both', topic: "safety", s: "A Safety Data Sheet (SDS) is used to:", c: ["Record a patient's diagnosis", "Identify chemical hazards and how to work with a product safely", "Set a ventilator tidal volume as the complete usual rule in ordinary practice", "Assign an IP address"], f: "The SDS (formerly MSDS) describes hazards, PPE, storage, and emergency actions for a chemical product. It is not a medical record or a device setting sheet.", src: "osha-elec" },
    { id: "cb095", ages: 'both', topic: "safety", s: "A standard ionizing-radiation trefoil sign is meant to:", c: ["Mark a quiet waiting room", "Warn of a radiation hazard in that area or on that source", "Label only a fire extinguisher as the complete usual rule in ordinary practice", "Show a wifi password"], f: "The trefoil is the standard ionizing-radiation warning symbol. Laser and MRI areas use their own distinctive warnings. Staff should heed posted signs and access rules.", src: "aami-cbet" },
    { id: "cb096", ages: 'both', topic: "safety", s: "Standard precautions in a healthcare facility include:", c: ["Never washing hands if gloves are in the room as the complete usual rule in ordinary practice", "Hand hygiene and using the PPE the task requires, treating body fluids as potentially infectious", "Reusing single-use needles to save money", "Eating in a soiled utility room to save time"], f: "Standard precautions assume that blood and body fluids may be infectious. Hand hygiene, appropriate PPE, safe sharps handling, and cleaning are core practices taught by CDC and required in facilities.", src: "cdc-precautions" },
    { id: "cb097", ages: 'both', topic: "safety", s: "CMS (Centers for Medicare and Medicaid Services) is important to hospitals in part because:", c: ["It manufactures infusion pumps", "It sets Conditions of Participation and recognizes accrediting organizations", "It writes Ohm's law", "It issues all state PE licenses as the complete usual rule in ordinary practice"], f: "CMS oversees federal healthcare payment programs and Conditions of Participation. It also grants deeming authority to certain accrediting bodies. It is not a device maker or a PE board.", src: "cms" },
    { id: "cb098", ages: 'both', topic: "safety", s: "AAMI standards such as EQ56 are used in healthcare technology management to:", c: ["Replace all electrical codes with a single essay as the complete usual rule in ordinary practice", "Guide medical equipment programs, including maintenance practices, in a consistent way", "Set the retail price of a CT scanner", "License physicians"], f: "AAMI EQ documents (including EQ56 for medical equipment programs and related EQ standards) give vocabulary and practice guidance for HTM programs. They do not replace electrical or building codes and are not a price list. Consult the current standard for the official text.", src: "aami-cbet" },
    { id: "cb099", ages: 'both', topic: "safety", s: "A CMMS in a biomedical department is used to:", c: ["Ventilate a patient", "Document work, schedule maintenance, and track equipment history", "Deliver a defibrillation shock as the complete usual rule in ordinary practice", "Mix chemotherapy"], f: "A computerized maintenance management system is the record of inventory, work orders, scheduled maintenance, and history used for compliance and performance. It is not a clinical treatment device.", src: "aami-cbet" },
    { id: "cb100", ages: 'both', topic: "safety", s: "An MRI warning sign is posted because:", c: ["The room is only a quiet library", "The strong magnetic field can pull ferromagnetic objects and is a serious safety hazard", "There is no difference from a waiting room as the complete usual rule in ordinary practice", "The sign is decorative only"], f: "MRI systems have a powerful magnetic field that can move ferromagnetic objects and also other hazards (for example, implants and time-varying fields). Access and screening rules exist to prevent projectile and implant injuries.", src: "aami-cbet" },
  ]
});
